## Submitted testbench
```systemverilog
module tb;

  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 8;                     // 125 MHz
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  logic rst = 1;

  // ------------------------------------------------------------
  // Testbench signals
  // ------------------------------------------------------------
  localparam logic [15:0] DEFAULT_PRESCALE = 16'd5;
  logic [15:0] prescale;
  logic [7:0]  s_axis_tdata;
  logic        s_axis_tvalid;
  logic        s_axis_tready;          // DUT output
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid_dut;      // DUT output
  logic        m_axis_tready_in;       // DUT input (always 1)
  logic [7:0]  rxd_reg;                // DUT input
  logic [7:0]  txd;
  logic        tx_busy;
  logic        rx_busy;
  logic        rx_overrun_error;
  logic        rx_frame_error;

  // ------------------------------------------------------------
  // DUT instantiation
  // ------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk            (clk),
    .rst            (rst),
    .s_axis_tdata   (s_axis_tdata),
    .s_axis_tvalid  (s_axis_tvalid),
    .s_axis_tready  (s_axis_tready),
    .m_axis_tdata   (m_axis_tdata),
    .m_axis_tvalid  (m_axis_tvalid_dut),
    .m_axis_tready  (m_axis_tready_in),
    .rxd            (rxd_reg),
    .txd            (txd),
    .tx_busy        (tx_busy),
    .rx_busy        (rx_busy),
    .rx_overrun_error (rx_overrun_error),
    .rx_frame_error   (rx_frame_error),
    .prescale       (prescale)
  );

  // ------------------------------------------------------------
  // Tie off unused or unneeded ports
  // ------------------------------------------------------------
  assign s_axis_tdata    = 8'd0;
  assign s_axis_tvalid   = 1'b0;
  assign m_axis_tready_in= 1'b1;
  assign prescale        = DEFAULT_PRESCALE;

  // ------------------------------------------------------------
  // Internal control logic for coverage point R14
  // ------------------------------------------------------------
  // detection of first word delivery (rising m_axis_tvalid)
  logic prev_m_axis_tvalid = 0;
  logic rising_detected    = 0;
  logic start_tx_immediate = 0;
  logic second_frame_active= 0;
  logic sending_second_frame_done = 0;

  // transmission state machine signals
  typedef enum logic [2:0] {TX_IDLE=3'd0, TX_START=3'd1, TX_DATA=3'd2,
                            TX_STOP=3'd3, TX_DONE=3'd4} tx_fsm_t;
  tx_fsm_t tx_fsm = TX_IDLE;

  // bit‑level timing
  logic [31:0] bit_clks;
  logic [31:0] bit_cnt   = 0;
  logic [3:0]  data_bit_idx = 0;
  logic [7:0]  data_to_send = 8'h00;

  // ------------------------------------------------------------
  // Prescale calculation (bits are transmitted in prescale*8 clocks)
  // ------------------------------------------------------------
  always_comb begin
    bit_clks = prescale * 8;   // number of clk cycles per UART bit
  end

  // ------------------------------------------------------------
  // Reset sequencing
  // ------------------------------------------------------------
  initial begin
    # (CLK_PERIOD*4);
    rst = 0;
    # (CLK_PERIOD*4);
  end

  // ------------------------------------------------------------
  // Monitor rising edge of m_axis_tvalid_dut to schedule second frame
  // ------------------------------------------------------------
  always @(posedge clk) begin
    if (rst) begin
      prev_m_axis_tvalid    <= 0;
      rising_detected       <= 0;
      start_tx_immediate    <= 0;
      second_frame_active   <= 0;
      sending_second_frame_done <= 0;
      tx_fsm                <= TX_IDLE;
    end else begin
      // detect rising edge of m_axis_tvalid_dut
      if (!prev_m_axis_tvalid && m_axis_tvalid_dut) begin
        rising_detected <= 1;
      end
      prev_m_axis_tvalid <= m_axis_tvalid_dut;

      // generate a one‑clock pulse to start the second frame
      if (rising_detected && !second_frame_active) begin
        start_tx_immediate <= 1;
      end else begin
        start_tx_immediate <= 0;
      end

      // --------------------------------------------------------
      // Transmission state machine (starts when start_tx_immediate = 1)
      // --------------------------------------------------------
      if (start_tx_immediate) begin
        second_frame_active <= 1;
        tx_fsm               <= TX_START;
        data_to_send         <= 8'h5A;        // payload for R14
        data_bit_idx         <= 0;
        bit_cnt              <= 0;
      end

      // --------------------------------------------------------
      // State machine execution
      // --------------------------------------------------------
      if (second_frame_active) begin
        case (tx_fsm)
          TX_START: begin
            rxd_reg <= 1'b0;                 // start bit = 0
            if (bit_cnt < bit_clks-1) begin
              bit_cnt <= bit_cnt + 1;
            end else begin
              bit_cnt   <= 0;
              tx_fsm    <= TX_DATA;
            end
          end

          TX_DATA: begin
            rxd_reg <= data_to_send[data_bit_idx];
            if (bit_cnt < bit_clks-1) begin
              bit_cnt <= bit_cnt + 1;
            end else begin
              bit_cnt   <= 0;
              data_bit_idx <= data_bit_idx + 1;
              if (data_bit_idx == 8) begin
                tx_fsm <= TX_STOP;
              end
            end
          end

          TX_STOP: begin
            rxd_reg <= 1'b1;                 // stop bit = 1
            if (bit_cnt < bit_clks-1) begin
              bit_cnt <= bit_cnt + 1;
            end else begin
              bit_cnt   <= 0;
              tx_fsm    <= TX_DONE;
            end
          end

          TX_DONE: begin
            tx_fsm     <= TX_IDLE;
            sending_second_frame_done <= 1;
          end

          default: tx_fsm <= TX_IDLE;
        endcase
      end
    end
  end

  // ------------------------------------------------------------
  // End of simulation when the second frame has been accepted
  // ------------------------------------------------------------
  always @(posedge clk) begin
    if (rst) begin
      // nothing
    end else if (sending_second_frame_done) begin
      // Give the DUT a few extra cycles for any pending checks,
      // then terminate the simulation.
      #1;
      $finish;
    end
  end

  // ------------------------------------------------------------
  // 60 s timeout guard
  // ------------------------------------------------------------
  initial begin
    #60000ms;
    $fatal(1, "simulation timeout");
  end

endmodule
